<?php declare(strict_types=1);$base=config('app.base_path');?><div class="page-header"><div><h1><?= htmlspecialchars($record['title'],ENT_QUOTES,'UTF-8')?></h1><p><?= (int)$record['duration_days']?> days / <?= (int)$record['duration_nights']?> nights · <?= htmlspecialchars($record['pricing_type'],ENT_QUOTES,'UTF-8')?></p></div><div class="page-actions"><a class="btn btn-secondary" href="<?= $base ?>/tourism/packages">Back</a><a class="btn btn-primary" href="<?= $base ?>/tourism/packages/<?= (int)$record['id']?>/edit">Edit</a></div></div><div class="card"><h2>Package Overview</h2><p><?= nl2br(htmlspecialchars((string)($record['description']??''),ENT_QUOTES,'UTF-8'))?></p><div class="stats"><div><strong>₹<?= number_format((float)($record['discount_price']??$record['base_price']),2)?></strong><span><?= $record['pricing_type']==='PER_GROUP'?'per group':'per person'?></span></div><div><strong><?= (int)($record['max_travellers']??0)?:'—'?></strong><span>max travellers</span></div><div><strong><?= htmlspecialchars($record['status'],ENT_QUOTES,'UTF-8')?></strong><span>status</span></div></div></div><div class="card"><h2>Itinerary Destinations</h2><?php if(empty($destinations)):?><p>No destinations assigned yet.</p><?php else:?><div class="itinerary"><?php foreach($destinations as $d):?><div class="itin"><div><strong>Day <?= (int)$d['day_number']?> · <?= htmlspecialchars($d['name'],ENT_QUOTES,'UTF-8')?></strong><div><?= htmlspecialchars((string)($d['district']??''),ENT_QUOTES,'UTF-8')?><?= !empty($d['city'])?' · '.htmlspecialchars($d['city'],ENT_QUOTES,'UTF-8'):''?></div><small><?= htmlspecialchars((string)($d['notes']??''),ENT_QUOTES,'UTF-8')?></small></div><form method="post" action="<?= $base ?>/tourism/packages/<?= (int)$record['id']?>/destinations/<?= (int)$d['id']?>/delete"><button class="link-button">Remove</button></form></div><?php endforeach;?></div><?php endif;?><hr><h3>Add Destination</h3><form method="post" action="<?= $base ?>/tourism/packages/<?= (int)$record['id']?>/destinations" class="inline-form"><select name="destination_id" required><option value="">Select destination...</option><?php foreach($all_destinations as $d):?><option value="<?= (int)$d['id']?>"><?= htmlspecialchars($d['name'].' · '.$d['district'],ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select><input type="number" min="1" name="day_number" value="1" placeholder="Day"><input type="number" min="1" name="sequence_no" value="1" placeholder="#"><input name="notes" placeholder="Itinerary note"><button class="btn btn-primary">Add</button></form></div><style>.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:20px}.stats div{padding:16px;background:#f8fafc;border-radius:12px}.stats strong,.stats span{display:block}.stats span{color:#64748b;margin-top:4px}.itin{display:flex;justify-content:space-between;gap:15px;padding:14px 0;border-bottom:1px solid #e2e8f0}.inline-form{display:grid;grid-template-columns:2fr .7fr .7fr 2fr auto;gap:10px;align-items:center}.inline-form input,.inline-form select{width:100%;box-sizing:border-box}@media(max-width:800px){.stats{grid-template-columns:1fr}.inline-form{grid-template-columns:1fr}}</style>